#include <iostream>
#include <type_traits>
template <typename T>
constexpr T square(T x) { return x * x; }

template <typename T>
struct MyCalculation {
  static constexpr T calculate(T value) {
    static_assert(std::is_arithmetic_v<T>, "Type must be arithmetic");
    return square(value) + value; 
  }
};

template <typename T>
struct MyCalculation<std::complex<T>> {
  static constexpr std::complex<T> calculate(std::complex<T> value) {
    return value * value + value;
  }
};

int main() {
  constexpr int resultInt = MyCalculation<int>::calculate(5);
  constexpr double resultDouble = MyCalculation<double>::calculate(2.5);
  constexpr std::complex<double> resultComplex = MyCalculation<std::complex<double>>::calculate({1.0, 2.0});
  std::cout << resultInt << std::endl; //Output: 30
  std::cout << resultDouble << std::endl; //Output: 8.25
  std::cout << resultComplex << std::endl; //Output: (2+5i)
  return 0;
}
